    let count = Arc::new(AtomicUsize::new(0));
    let mut workers = Vec::new();
    for _ in 0..2 {
        let local = Arc::clone(&count);
        workers.push(thread::spawn(move || {
            for _ in 0..100 { local.fetch_add(1, Ordering::SeqCst); }
        }));
    }
