use std::io::{self, BufRead, Cursor};
fn invalid(message: &str) -> io::Error { io::Error::new(io::ErrorKind::InvalidData, message) }
fn total(input: &str) -> io::Result<u32> {
    if input.len() > 32 { return Err(invalid("input too long")); }
    let mut sum = 0;
    for (index, line) in Cursor::new(input.as_bytes()).lines().enumerate() {
        if index >= 2 { return Err(invalid("too many lines")); }
        let n: u32 = line?.parse().map_err(|_| invalid("invalid integer"))?;
        if !(1..=60).contains(&n) { return Err(invalid("invalid minutes")); }
        sum += n;
    }
    Ok(sum)
}
fn main() {
    match total("15\n20\n5\n") {
        Ok(n) => println!("{n}"),
        Err(error) => println!("{error}"),
    }
}

